fn append_chunked_body(dst: &mut String, body: &str, parts: usize) {
    let parts = parts.max(1).min(body.len().max(1));
    let mut start = 0usize;
    for part in 0..parts {
        let remaining = body.len() - start;
        let take = if part + 1 == parts {
            remaining
        } else {
            remaining / (parts - part)
        };
        let end = start + take;
        let seg = &body[start..end];
        dst.push_str(&format!("{:x}\r\n{}\r\n", seg.len(), seg));
        start = end;
    }
    dst.push_str("0\r\n");
}

fn build_large_absolute_url_corpus() -> Vec<u8> {
    let mut out = String::new();
    for i in 0..120_000u32 {
        let scheme = if i % 3 == 0 { "https" } else { "http" };
        let host = format!("node{:05}.example{}.com", i % 10000, i % 17);
        let user = format!("user{}", i % 97);
        let pass = format!("pass{:x}", i.wrapping_mul(0x45d9f3b));
        let port = 8000 + (i % 1000);
        let path = format!(
            "/api/v1/tenant/{}/bucket/{}/object/{}/part/{}",
            i % 251,
            i % 1021,
            i,
            i % 13
        );
        let query = format!(
            "x={}&y={}&mode=perf&tag=url&repeat={}&alpha=one&beta=two&gamma=three",
            i,
            i.wrapping_mul(7),
            i % 29
        );
        let frag = format!("frag{}", i % 41);
        out.push_str(&format!(
            "{}://{}:{}@{}:{}/{}?{}#{}\n",
            scheme,
            user,
            pass,
            host,
            port,
            path.trim_start_matches('/'),
            query,
            frag
        ));
        if i % 11 == 0 {
            out.push_str(&format!("{}:{}\n", host, 443 + (i % 7)));
        }
    }
    out.into_bytes()
}

